```php
public function verify_coupon($code, array $applicationInfo)
{
    // Carregar modelo de Cupons
    $this->load->model('coupons_model');

    // Buscar o cupom pelo código
    $coupon = $this->coupons_model->get_coupon_by_code($code);

    if (!$coupon) {
        return ['error' => 'Código de cupom inválido'];
    }

    // Verificar validade do cupom
    $now = new DateTime();
    $startDate = new DateTime($coupon->valid_from);
    $endDate = new DateTime($coupon->valid_to);

    if ($now < $startDate || $now > $endDate) {
        return ['error' => 'O cupom expirou'];
    }

    // Verificar se o cupom ainda pode ser usado (se for reutilizável)
    if ($coupon->is_reusable && !empty($coupon->usage_counts)) {
        foreach ($coupon->usage_counts as $dateStr => $_) {
            $usageDate = new DateTime($dateStr);
            if ($usageDate <= $now) {
                return ['error' => 'Este cupom já foi utilizado'];
            }
        }
    }

    // Aplicar desconto conforme configurado
    switch ($coupon->discount_type) {
        case '1': // Percentual
            $totalSpend = floatval($applicationInfo['total_spent']);
            $discountAmount = min((float)$coupon->discount_value / 100, $totalSpend);
            break;
        case '2': // Valor fixo
            $discountAmount = min((float)$coupon->discount_value, $totalSpend);
            break;
        default:
            continue 2; // Ignorar tipos desconhecidos
    }

    // Registrar uso do cupom
    $this->coupons_model->record_usage($coupon->id, $now->format('Y-m-d'));

    return [
        'success' => true,
        'discount_amount' => round($discountAmount, 2),
        'message' => 'Cupom aplicado com sucesso!'
    ];
}
```

